12	    /// Signed area of the triangle `(p, q, r)`, doubled.
13	    pub(super) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
14	        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
15	        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
16	    }
17	
18	    /// Check if two points are equal.
19	    pub(super) fn equals(&self, p1: usize, p2: usize) -> bool {
20	        let (p1, p2) = (&self.nodes[p1], &self.nodes[p2]);
21	        p1.x == p2.x && p1.y == p2.y
22	    }
