24	    #[allow(clippy::too_many_arguments)]
25	    pub(super) fn point_in_triangle(
26	        &self,
27	        ax: f64,
28	        ay: f64,
29	        bx: f64,
30	        by: f64,
31	        cx: f64,
32	        cy: f64,
33	        px: f64,
34	        py: f64,
35	    ) -> bool {
36	        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
37	            && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
38	            && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
39	    }
