186	    /// Link two polygon vertices with a bridge; if the vertices belong to the same
187	    /// ring, it splits the polygon into two. If one belongs to the outer ring and
188	    /// another to a hole, it merges it into a single ring.
189	    pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
190	        let (ai, ax, ay) = {
191	            let n = &self.nodes[a];
192	            (n.i, n.x, n.y)
193	        };
194	        let (bi, bx, by) = {
195	            let n = &self.nodes[b];
196	            (n.i, n.x, n.y)
197	        };
198	        let a2 = self.construct(ai, ax, ay);
199	        let b2 = self.construct(bi, bx, by);
200	        let an = self.nodes[a].next;
201	        let bp = self.nodes[b].prev;
202	
203	        self.nodes[a].next = b;
204	        self.nodes[b].prev = a;
205	
206	        self.nodes[a2].next = an;
207	        self.nodes[an].prev = a2;
208	
209	        self.nodes[b2].next = a2;
210	        self.nodes[a2].prev = b2;
211	
212	        self.nodes[bp].next = b2;
213	        self.nodes[b2].prev = bp;
214	
215	        b2
216	    }
