504	    /// Find a bridge between vertices that connects a hole with an outer ring and
505	    /// link it.
506	    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
507	        let bridge = self.find_hole_bridge(hole, outer_node);
